mapper.select:
SELECT id, article_title, create_time FROM tb_article WHERE is_delete = 0 AND status = 1
AND (create_time < #{cursorTime} OR (create_time = #{cursorTime} AND id < #{cursorId}))
ORDER BY create_time DESC, id DESC LIMIT #{limit}

SELECT a.id, article_cover, article_title, type, is_top, a.is_delete, a.status, a.create_time, category_name, t.id AS tag_id, t.tag_name FROM ( SELECT id, article_cover, article_title, type, is_top, is_delete, status, create_time, category_id FROM tb_article
is_delete = #{condition.isDelete}
and article_title like concat('%',#{condition.keywords},'%')
and status = #{condition.status}
and category_id = #{condition.categoryId}
and type = #{condition.type}
and id in ( SELECT article_id FROM tb_article_tag WHERE tag_id = #{condition.tagId} )
ORDER BY is_top DESC, id DESC LIMIT #{current},#{size} ) a LEFT JOIN tb_category c ON a.category_id = c.id LEFT JOIN tb_article_tag atg ON a.id = atg.article_id LEFT JOIN tb_tag t ON t.id = atg.tag_id ORDER BY is_top DESC, a.id DESC

SELECT COUNT(*)
FROM tb_article a

    a.is_delete = #{condition.isDelete}

        AND a.article_title LIKE CONCAT('%', #{condition.keywords}, '%')


        AND a.status = #{condition.status}


        AND a.category_id = #{condition.categoryId}


        AND a.type = #{condition.type}


        AND EXISTS (
            SELECT 1
            FROM tb_article_tag tat
            WHERE tat.article_id = a.id
              AND tat.tag_id = #{condition.tagId}
        )
